import React, { useState } from 'react';
import { LayoutDashboard, Users, FlaskConical, Settings, Bell, AlertTriangle, FileText, CheckCircle2, ArrowRight } from 'lucide-react';

// --- Mock Data --- //
const patientData = {
  name: 'Robert Miller',
  id: 'RM-48291',
  age: 68,
  diagnosis: 'Stage IV Non-Small Cell Lung Cancer (NSCLC)',
  biomarkers: ['EGFR Exon 19 Deletion', 'PD-L1 TPS < 1%'],
  lastUpdate: '2 hours ago',
};

const trialMatches = [
  {
    nctId: 'NCT04886800',
    title: 'A Study of Amivantamab and Lazertinib in EGFR-Mutated Advanced NSCLC',
    confidence: 92,
    status: 'Recruiting',
    matchReasons: ['Patient has confirmed EGFR mutation', 'Age > 18 years', 'ECOG performance status 0-1'],
    mismatchReasons: [],
  },
  {
    nctId: 'NCT05333794',
    title: 'A Study of Patritumab Deruxtecan for Metastatic EGFR-Mutated NSCLC',
    confidence: 78,
    status: 'Recruiting',
    matchReasons: ['Patient has confirmed EGFR mutation', 'Received prior TKI therapy'],
    mismatchReasons: ['Requires brain metastasis screening'],
  },
  {
    nctId: 'NCT04429029',
    title: 'A Study of Telisotuzumab Vedotin in c-Met+ Advanced/Metastatic NSCLC',
    confidence: 45,
    status: 'Recruiting',
    matchReasons: ['Stage IV NSCLC diagnosis'],
    mismatchReasons: ['Patient c-Met status is unknown/negative'],
  },
];

// --- Main Component --- //
export default function TrialMatchPrototype() {
  const [currentScreen, setCurrentScreen] = useState('dashboard');
  const [activePatient, setActivePatient] = useState(null);

  const navigateToPatient = (patient) => {
    setActivePatient(patient);
    setCurrentScreen('patientDetail');
  };

  const SideBar = () => (
    <div className="w-64 bg-white border-r border-gray-200 flex flex-col">
      <div className="p-4 border-b border-gray-200">
        <h1 className="text-xl font-bold text-blue-800">TrialMatch AI</h1>
      </div>
      <nav className="flex-1 p-4 space-y-2">
        <NavItem icon={<LayoutDashboard size={20} />} label="Dashboard" screen="dashboard" />
        <NavItem icon={<Users size={20} />} label="My Patients" screen="patients" />
        <NavItem icon={<FlaskConical size={20} />} label="Clinical Trials" screen="trials" />
        <NavItem icon={<Settings size={20} />} label="Settings" screen="settings" />
      </nav>
      <div className="p-4 border-t border-gray-200">
        <div className="flex items-center">
          <img src="https://i.pravatar.cc/40?u=drAinsworth" alt="Dr. Eleanor Ainsworth" className="w-10 h-10 rounded-full" />
          <div className="ml-3">
            <p className="font-semibold text-sm">Dr. E. Ainsworth</p>
            <p className="text-xs text-gray-500">Oncologist</p>
          </div>
        </div>
      </div>
    </div>
  );

  const NavItem = ({ icon, label, screen }) => (
    <button
      onClick={() => setCurrentScreen(screen)}
      className={`w-full flex items-center space-x-3 px-3 py-2 rounded-md text-sm font-medium transition-all duration-200 ${currentScreen === screen ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-100'}`}>
      {icon}
      <span>{label}</span>
    </button>
  );

  const DashboardScreen = () => (
    <div className="space-y-8">
      <header>
        <h2 className="text-3xl font-bold text-gray-800">Dr. Ainsworth's Dashboard</h2>
        <p className="text-gray-500 mt-1">Welcome back, here's your clinical trial overview.</p>
      </header>

      {/* Key Action Alert */}
      <div
        onClick={() => navigateToPatient(patientData)}
        className="bg-yellow-50 border-l-4 border-yellow-400 p-4 flex items-start space-x-4 rounded-r-lg cursor-pointer hover:shadow-lg transition-shadow duration-200">
        <AlertTriangle className="text-yellow-500 mt-1 flex-shrink-0" size={24} />
        <div>
          <h3 className="font-semibold text-yellow-800">New High-Confidence Matches Found</h3>
          <p className="text-sm text-yellow-700 mt-1">Our AI has identified new potential trial matches for 2 of your patients based on recent EHR updates. Patient <span className="font-semibold">Robert Miller</span> has a 92% confidence match.</p>
          <div className="text-sm font-semibold text-blue-600 mt-2 flex items-center">View Match Details <ArrowRight size={16} className="ml-1"/></div>
        </div>
      </div>

      {/* Metrics */}
       <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <MetricCard title="Active Patients Monitored" value="87" />
        <MetricCard title="Patients Enrolled (Q2)" value="14" change="+2" />
        <MetricCard title="Pending Pre-Screenings" value="3" />
      </div>

      {/* Enrollment Chart Placeholder */}
      <div>
        <h3 className="text-lg font-semibold text-gray-700 mb-3">Trial Enrollment Trend (Last 6 Months)</h3>
        <div className="bg-white p-4 rounded-lg border border-gray-200 flex items-end justify-between h-48 space-x-4">
            <Bar month="Jan" value={4} max={10} />
            <Bar month="Feb" value={6} max={10} />
            <Bar month="Mar" value={5} max={10} />
            <Bar month="Apr" value={8} max={10} />
            <Bar month="May" value={9} max={10} />
            <Bar month="Jun" value={7} max={10} />
        </div>
      </div>
    </div>
  );

  const MetricCard = ({ title, value, change }) => (
    <div className="bg-white p-5 rounded-lg border border-gray-200 shadow-sm">
      <p className="text-sm text-gray-500">{title}</p>
      <div className="flex items-baseline space-x-2 mt-1">
        <p className="text-3xl font-bold text-gray-800">{value}</p>
        {change && <p className="text-sm font-semibold text-teal-600">{change}</p>}
      </div>
    </div>
  );

  const Bar = ({ month, value, max }) => (
    <div className="flex-1 flex flex-col items-center">
        <div className="w-full h-full flex items-end">
            <div style={{ height: `${(value / max) * 100}%` }} className="w-full bg-blue-500 rounded-t-md hover:bg-blue-600 transition-colors duration-200"></div>
        </div>
        <p className="text-xs text-gray-500 mt-2">{month}</p>
    </div>
  );

  const PatientDetailScreen = () => (
    <div className="space-y-6">
      <header>
        <button onClick={() => setCurrentScreen('dashboard')} className="text-sm text-blue-600 hover:underline mb-2">← Back to Dashboard</button>
        <h2 className="text-3xl font-bold text-gray-800">Trial Matches for {activePatient?.name}</h2>
        <p className="text-gray-500 mt-1">{activePatient?.diagnosis} (ID: {activePatient?.id})</p>
      </header>

      {trialMatches.map((trial, index) => (
        <TrialCard key={trial.nctId} trial={trial} isTopMatch={index === 0} />
      ))}
    </div>
  );

  const TrialCard = ({ trial, isTopMatch }) => (
    <div className={`bg-white rounded-lg border ${isTopMatch ? 'border-blue-500 shadow-lg' : 'border-gray-200 shadow-sm'} overflow-hidden transition-all duration-200`}>
      {isTopMatch && <div className="bg-blue-500 text-white text-xs font-bold uppercase p-2 text-center tracking-wider">Highest Confidence Match</div>}
      <div className="p-6">
        <div className="flex justify-between items-start">
          <div>
            <p className="font-semibold text-lg text-gray-800">{trial.title}</p>
            <p className="text-sm text-gray-500 mt-1">{trial.nctId} · <span className="font-medium text-teal-600">{trial.status}</span></p>
          </div>
          <div className="text-center ml-6 flex-shrink-0">
            <p className="text-3xl font-bold text-blue-600">{trial.confidence}%</p>
            <p className="text-xs text-gray-500">Match Score</p>
          </div>
        </div>

        <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
          <div>
            <h4 className="text-sm font-semibold text-gray-600">Matching Criteria Met:</h4>
            <ul className="mt-1 list-disc list-inside space-y-1 text-sm text-gray-700">
              {trial.matchReasons.map(reason => <li key={reason}>{reason}</li>)}
            </ul>
          </div>
          <div>
            <h4 className={`text-sm font-semibold ${trial.mismatchReasons.length > 0 ? 'text-red-600' : 'text-gray-600'}">Potential Mismatches:</h4>
            {trial.mismatchReasons.length > 0 ? (
              <ul className="mt-1 list-disc list-inside space-y-1 text-sm text-red-700">
                {trial.mismatchReasons.map(reason => <li key={reason}>{reason}</li>)}
              </ul>
            ) : (
              <p className="text-sm text-gray-500 mt-1">None identified.</p>
            )}
          </div>
        </div>

        {isTopMatch && (
          <div className="mt-6 pt-4 border-t border-gray-200 flex justify-end">
            <button 
              onClick={() => setCurrentScreen('confirmation')}
              className="bg-blue-600 text-white font-semibold py-2 px-5 rounded-lg flex items-center space-x-2 hover:bg-blue-700 transition-all duration-200 shadow-sm hover:shadow-md">
              <FileText size={18} />
              <span>Generate Pre-Screening Package</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );

  const ConfirmationScreen = () => (
    <div className="text-center bg-white p-12 rounded-lg border border-gray-200 shadow-sm">
      <CheckCircle2 className="mx-auto text-teal-500" size={64} />
      <h2 className="mt-6 text-2xl font-bold text-gray-800">Pre-Screening Package Generated</h2>
      <p className="mt-2 text-gray-600 max-w-md mx-auto">
        The package for <span className="font-semibold">{activePatient?.name}</span> and trial <span className="font-semibold">{trialMatches[0].nctId}</span> has been securely sent to your clinical trial coordination team.
      </p>
      <button onClick={() => setCurrentScreen('dashboard')} className="mt-8 bg-gray-100 text-gray-700 font-semibold py-2 px-5 rounded-lg hover:bg-gray-200 transition-all duration-200">
        Return to Dashboard
      </button>
    </div>
  );

  const PlaceholderScreen = ({title}) => (
      <div>
          <h2 className="text-3xl font-bold text-gray-800">{title}</h2>
          <p className="text-gray-500 mt-2">This section is under development.</p>
      </div>
  );


  const renderScreen = () => {
    switch (currentScreen) {
      case 'dashboard': return <DashboardScreen />;
      case 'patientDetail': return <PatientDetailScreen />;
      case 'confirmation': return <ConfirmationScreen />;
      case 'patients': return <PlaceholderScreen title="My Patients" />;
      case 'trials': return <PlaceholderScreen title="Clinical Trials" />;
      case 'settings': return <PlaceholderScreen title="Settings" />;
      default: return <DashboardScreen />;
    }
  };

  return (
    <div className="flex h-screen bg-gray-50 font-sans text-gray-900" style={{ fontFamily: `-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif` }}>
      <SideBar />
      <main className="flex-1 p-8 overflow-y-auto">
        <div className="max-w-5xl mx-auto">
          {renderScreen()}
        </div>
      </main>
    </div>
  );
}

